$\begin{align}
&\phantom{=}\dfrac{d}{dx}\left(\dfrac1x\cos(x)\right)
\\\\
&=\dfrac{d}{dx}\left(\dfrac1x\right)\cos(x)+\dfrac1x\dfrac{d}{dx}(\cos(x))&&\gray{\text{The product rule}}
\\\\
&=\dfrac{d}{dx}\left(x^{-1}\right)\cos(x)+\dfrac1x\dfrac{d}{dx}(\cos(x))&&\gray{\text{Write }\dfrac1x\text{ as a power}}
\\\\
&=-1x^{-2}\cdot \cos(x)+\dfrac1x\cdot (-\sin(x))&&\gray{\text{Differentiate }x^{-1}\text{ and }\cos(x)}
\\\\
&=-\dfrac1{x^{2}}\cdot \cos(x)+\dfrac1x\cdot (-\sin(x))&&\gray{\text{Write as positive exponents}}
\\\\
&=\dfrac{-\cos(x)-x\sin(x)}{x^2}&&\gray{\text{Common denominator}}
\end{align}$
